#!/usr/bin/env bash
# M2: a JSON-wired program over Connect reading one message holding one Any
# (spike/m2/Main.elm.in), generated by this branch's CLI under codec=json:
# (a) the method binding the package's registry, (b) the method binding the
# empty one and the client setting the package's with Rpc.withRegistry,
# (c) the message without its Any, the empty registry. First on the
# codec_both corpus package with WellKnown's repeated `anys` removed
# (spike/m2/one; spike/m2/none drops `any` too), then on a synthetic package
# of 60 messages at depth one with an Any in Msg0 (spike/synth.py).
# SYNTH_ONLY=1 skips the corpus package.
#   spike/m2.sh WORK CLI_BASE
set -euo pipefail
work="$1"; cli="$2"
here="$(cd "$(dirname "$0")/.." && pwd)"
app() { # dir generated module type registry decoder client
  local d="$1"
  rm -rf "$d"; mkdir -p "$d/app/src"; ln -s "$2" "$d/generated"
  python3 - "$d/app" "$here/src" "$here/spike/m2/Main.elm.in" "$3" "$4" "$5" "$6" "$7" <<'PY'
import json, sys
out, rt, tmpl, mod, ty, reg, dec, cl = sys.argv[1:]
json.dump({'type': 'application', 'source-directories': ['src', '../generated', rt], 'elm-version': '0.19.2',
           'dependencies': {'direct': {'elm/bytes': '1.0.8', 'elm/core': '1.0.5', 'elm/http': '2.0.0', 'elm/json': '1.1.4', 'elm/time': '1.0.0'},
                            'indirect': {'elm/file': '1.0.5'}},
           'test-dependencies': {'direct': {}, 'indirect': {}}}, open(out + '/elm.json', 'w'), indent=4)
s = open(tmpl).read().replace('@MODULE@', mod).replace('@TYPE@', ty).replace('@REGISTRY@', reg).replace('@DECODER@', dec).replace('@CLIENT@', cl)
open(out + '/src/Main.elm', 'w').write(s)
PY
}
measure() { "$here/spike/make.sh" "$1" "$2"; "$here/spike/size.sh" "$1/app/main.js" "$2"; }
with() { printf '\n        |> Rpc.withRegistry %s.registry' "$1"; }

if [ -z "${SYNTH_ONLY:-}" ]; then
for v in one none; do
  rm -rf "$work/gen-$v"
  "$cli" gen -I "$here/spike/m2/$v" codec.proto other.proto --codec json --out "$work/gen-$v" > /dev/null
done
app "$work/codec-a" "$work/gen-one" Codec.V1 WellKnown Codec.V1.registry Codec.V1.decodeWellKnownWith ""
app "$work/codec-b" "$work/gen-one" Codec.V1 WellKnown Proto.Registry.empty Codec.V1.decodeWellKnownWith "$(with Codec.V1)"
app "$work/codec-c" "$work/gen-none" Codec.V1 WellKnown Proto.Registry.empty '(\_ -> Codec.V1.decodeWellKnown)' ""
for v in a b c; do measure "$work/codec-$v" "codec_both ($v)"; done
fi

# SYNTH_N, 60 by default; at 30 the slope between the two sizes is the
# table's cost per message.
n="${SYNTH_N:-60}"
for v in any none; do
  rm -rf "$work/synth-$v"
  if [ $v = any ]; then a=1; else a=0; fi
  SYNTH_PARENT=chain1 SYNTH_ANY=$a python3 "$here/spike/synth.py" "$n" json "$work/synth-$v"
  "$cli" gen -I "$work/synth-$v/proto" synth/v1/synth.proto --codec json --out "$work/synth-$v/generated" > /dev/null
done
app "$work/synth-a" "$work/synth-any/generated" Synth.V1 Msg0 Synth.V1.registry Synth.V1.decodeMsg0With ""
app "$work/synth-b" "$work/synth-any/generated" Synth.V1 Msg0 Proto.Registry.empty Synth.V1.decodeMsg0With "$(with Synth.V1)"
app "$work/synth-c" "$work/synth-none/generated" Synth.V1 Msg0 Proto.Registry.empty '(\_ -> Synth.V1.decodeMsg0)' ""
for v in a b c; do measure "$work/synth-$v" "synth$n ($v)"; done
